mapper.sql:
with assetHold as (select gavInfo.finprodAbbr,gavInfo.finprodMarketId,gavInfo.portFolioName, gavInfo.marketValue,gavInfo.dscCostAmt,gavInfo.shareAmt, round(nvl(gavInfo.marketValue,0)/ppvInfo.tdyAssetValue*100,2) as marketValueRatio,gavInfo.portfolioId,ppvInfo.tdyAssetValue, gavInfo.portfolioId1, gavInfo.ptlIssueType,gavInfo.assetRatioTemp from (select psv.CDATE cdate,psv.PORTFOLIO_ID portfolioId,psv.FINPROD_ID finprodId, psv.SHARE_AMT shareAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*psv.DSC_COST_AMT when fpt.TYPE_6 = 'L02' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_6 = 'L02' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) else (NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) end as marketValue, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*(NVL(psv.TDY_INTINCEXP,0)) when fpt.TYPE_6 = 'L02' then -1*(NVL(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(NVL(psv.TDY_INTINCEXP,0)) else NVL(psv.TDY_INTINCEXP,0) end as tdyIntincexp, pp.PORTFOLIO_NAME portFolioName,fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr,
T2.RAISE_TYPE ptlIssueType,
pp.PORTFOLIO_ID portfolioId1,
case when fp.FINPROD_TYPE2 = 'F10' and msp.CLOSE_PRICE is not null and msp.C_SHARES is not null then msp.CLOSE_PRICE * msp.C_SHARES when fp.FINPROD_TYPE2 = 'F06' and jji.valuation is not null and jji.cShares is not null then jji.valuation * jji.cShares when fp.FINPROD_TYPE2 = 'F01' and mbvi1.price is not null and mbvi1.ISSUE_AMT is not null then mbvi1.price * mbvi1.ISSUE_AMT * 100 when fp.FINPROD_TYPE2 = 'F01' and mbvi2.price is not null and mbvi2.ISSUE_AMT is not null then mbvi2.price * mbvi2.ISSUE_AMT * 100 else null end as assetRatioTemp
from PTL_SEC_VALUTION psv inner join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID inner join FIN_PRODUCT fp on fp.FINPROD_ID=psv.FINPROD_ID
and fp.FINPROD_TYPE2 != 'F28' and fp.FINPROD_TYPE2 is not null
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID
LEFT JOIN PA_PTL_PORTFOLIO T2 ON pp.PORTFOLIO_ID = T2.PORTFOLIO_ID /*计算资产占比 start*/ /*债券*/ left join(select a.FINPROD_MARKET_ID, a.ISSUE_AMT, a.price from ( SELECT distinct BOND.VALUE_DATE AS valueDate, BOND.PRICE AS price,/*市价全价*/ BOND.VALUE_SOURCE valueSource, T1.ISSUE_AMT / 10000 ISSUE_AMT,/*发行金额*/ T1.FINPROD_MARKET_ID FINPROD_MARKET_ID, T1.TRADE_MARKET TRADE_MARKET, ROW_NUMBER() OVER (PARTITION BY T1.FINPROD_MARKET_ID ORDER BY BOND.VALUE_DATE desc ) as rn FROM MST_BOND_VALUATION_INFO BOND left join FIN_PRODUCT T1 on T1.FINPROD_MARKET_ID = BOND.SEC_ID WHERE T1.FINPROD_TYPE = 'F01' AND T1.CCY = 'CNY' and BOND.VALUE_SOURCE = 'CBC'
and TO_DATE(to_char(BOND.VALUE_DATE,'yyyy-mm-dd'),'YYYY-MM-DD') <= TO_DATE(#{searchDate},'YYYY-MM-DD')
) a where a.rn = 1) mbvi1 on mbvi1.FINPROD_MARKET_ID = fp.finprod_market_id and fp.FINPROD_TYPE2 = 'F01' and fp.TRADE_MARKET = '01' left join( select a.FINPROD_MARKET_ID, a.ISSUE_AMT, a.price from ( SELECT distinct BOND.VALUE_DATE AS valueDate, BOND.PRICE AS price,/*市价全价*/ BOND.VALUE_SOURCE valueSource, T1.ISSUE_AMT / 10000 ISSUE_AMT,/*发行金额*/ T1.FINPROD_MARKET_ID FINPROD_MARKET_ID, T1.TRADE_MARKET TRADE_MARKET, ROW_NUMBER() OVER (PARTITION BY T1.FINPROD_MARKET_ID ORDER BY BOND.VALUE_DATE desc ) as rn FROM MST_BOND_VALUATION_INFO BOND left join FIN_PRODUCT T1 on T1.FINPROD_MARKET_ID = BOND.SEC_ID WHERE T1.FINPROD_TYPE = 'F01' AND T1.CCY = 'CNY' and BOND.VALUE_SOURCE = 'CBC'
and TO_DATE(to_char(BOND.VALUE_DATE,'yyyy-mm-dd'),'YYYY-MM-DD') <= TO_DATE(#{searchDate},'YYYY-MM-DD')
) a where a.rn = 1) mbvi2 on mbvi2.FINPROD_MARKET_ID = fp.finprod_market_id and fp.FINPROD_TYPE2 = 'F01' and fp.TRADE_MARKET != '01' /*基金*/ left join(select a.cShares, a.finprodMarketId, a.valuation from ( SELECT P.FINPROD_MARKET_ID finprodMarketId, V.VAL_DATE valDate, V.VALUATION valuation, /*单位净值*/ V.C_SHARES cShares,/*基金行情总份额值*/ ROW_NUMBER() OVER (PARTITION BY P.FINPROD_MARKET_ID ORDER BY V.VAL_DATE desc ) as rn FROM FIN_PRODUCT P INNER JOIN FIN_PRODUCT_VALUATION V ON P.FINPROD_MARKET_ID = V.FINPROD_ID and p.FINPROD_TYPE = V.FINPROD_TYPE INNER JOIN FIN_PRODUCT_TYPE TYPE ON P.FINPROD_ID = TYPE.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO CUST ON CUST.CUSTOMER_ID = P.MANAGER AND CUST.IS_ASSTE_MANAGER = 'Y' WHERE P.FINPROD_TYPE = 'F06'
and TO_DATE(to_char(V.VAL_DATE,'yyyy-mm-dd'),'YYYY-MM-DD') <= TO_DATE(#{searchDate},'YYYY-MM-DD')
)a where a.rn = 1) jji on jji.finprodMarketId = fp.finprod_market_id and fp.FINPROD_TYPE2 = 'F06' /*股票*/ left join (select a.CLOSE_PRICE, a.C_SHARES, a.SHARES_ID, a.DEAL_DATE from ( select CLOSE_PRICE, C_SHARES, DEAL_DATE, SHARES_ID, ROW_NUMBER() OVER (PARTITION BY SHARES_ID ORDER BY DEAL_DATE desc ) as rn from mst_share_price where 1=1
and TO_DATE(to_char(DEAL_DATE,'yyyy-mm-dd'),'YYYY-MM-DD') <= TO_DATE(#{searchDate},'YYYY-MM-DD')
)a where a.rn = 1) msp on msp.shares_id = fp.finprod_market_id and fp.FINPROD_TYPE2 = 'F10' /*计算资产占比 end*/
where 1=1
AND fp.FINPROD_MARKET_ID IN
#{item}
and to_char(psv.CDATE,'yyyy-mm-dd') = #{searchDate}
)gavInfo left join (select ppv.CDATE cdate,ppv.PORTFOLIO_ID portfolioId,nvl(ppv.TDY_ASSET_VALUE,0) tdyAssetValue from PTL_PORTFOLIO_VALUATION ppv where 1=1
and to_char(ppv.CDATE,'yyyy-mm-dd')= #{searchDate}
)ppvInfo on ppvInfo.portfolioId=gavInfo.portfolioId and ppvInfo.cdate=gavInfo.cdate where ppvInfo.tdyAssetValue !=0 )

mapper.select:
select assetHold1.finprodMarketId,assetHold1.finprodAbbr,null portFolioName,sum(assetHold1.marketValue) as marketValue, sum(assetHold1.dscCostAmt) as dscCostAmt,sum(assetHold1.shareAmt) as shareAmt, round(sum(nvl(assetHold1.marketValue,0))/sum(assetHold1.tdyAssetValue)*100,2) as marketValueRatio,null portfolioId,'02' as hasChildren ,'root' parentInfo,assetHold1.finprodMarketId childInfo, null belongInstitutionCodeNew, assetHold1.ptlIssueType from ( SELECT assetHold.*, DATAINST.BELONG_INSTITUTION_CODE belongInstitutionCode FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId1 = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1 group by assetHold1.finprodMarketId,assetHold1.finprodAbbr,assetHold1.ptlIssueType union all select null finprodMarketId,null finprodAbbr,assetHold1.portFolioName,assetHold1.marketValue,assetHold1.dscCostAmt,assetHold1.shareAmt, assetHold1.marketValueRatio,assetHold1.portfolioId,'01' as hasChildren ,assetHold1.finprodMarketId parentInfo,assetHold1.portFolioName childInfo, assetHold1.belongInstitutionCode belongInstitutionCodeNew, assetHold1.ptlIssueType from ( SELECT assetHold.*, DATAINST.BELONG_INSTITUTION_CODE belongInstitutionCode FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId1 = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1

select.if:
select assetHold1.finprodMarketId,assetHold1.finprodAbbr,null portFolioName,sum(assetHold1.marketValue) as marketValue, sum(assetHold1.dscCostAmt) as dscCostAmt,sum(assetHold1.shareAmt) as shareAmt, round(sum(nvl(assetHold1.marketValue,0))/sum(assetHold1.tdyAssetValue)*100,2) as marketValueRatio,null portfolioId,'02' as hasChildren ,'root' parentInfo,assetHold1.finprodMarketId childInfo,null ptlIssueType, case when assetHold1.assetRatioTemp > 0 then (sum(assetHold1.marketValue)/assetHold1.assetRatioTemp)*100 else null end as assetRatio from ( SELECT assetHold.* FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId1 = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1 WHERE decode(NVL(assetHold1.shareAmt,0),0,NVL(assetHold1.marketValue,0),NVL(assetHold1.shareAmt,0)) !=0 group by assetHold1.finprodMarketId,assetHold1.finprodAbbr,assetHold1.assetRatioTemp

select null finprodMarketId,null finprodAbbr,assetHold1.portFolioName,assetHold1.marketValue,assetHold1.dscCostAmt,NVL(assetHold1.shareAmt,0) shareAmt, assetHold1.marketValueRatio,assetHold1.portfolioId,'01' as hasChildren ,assetHold1.finprodMarketId parentInfo,assetHold1.portFolioName childInfo, assetHold1.belongInstitutionCode belongInstitutionCodeNew,assetHold1.ptlIssueType ptlIssueType, case when assetHold1.assetRatioTemp > 0 then (assetHold1.marketValue/assetHold1.assetRatioTemp)*100 else null end as assetRatio from ( SELECT assetHold.*, DATAINST.BELONG_INSTITUTION_CODE belongInstitutionCode FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId1 = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1 where assetHold1.finprodMarketId = #{parentId} AND decode(NVL(assetHold1.shareAmt,0),0,NVl(assetHold1.marketValue,0),assetHold1.shareAmt) !=0

select assetHold1.finprodMarketId,assetHold1.finprodAbbr,null portFolioName,sum(assetHold1.marketValue) as marketValue, sum(assetHold1.dscCostAmt) as dscCostAmt,sum(assetHold1.shareAmt) as shareAmt, sum(assetHold1.marketValueRatio) as marketValueRatio,null portfolioId,'02' as hasChildren ,'root' parentInfo,assetHold1.finprodMarketId childInfo,assetHold1.ptlIssueType ptlIssueType, case when assetHold1.assetRatioTemp > 0 then (sum(assetHold1.marketValue)/assetHold1.assetRatioTemp)*100 else null end as assetRatio from ( SELECT assetHold.* FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId1 = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1 WHERE NVL(assetHold1.shareAmt,0)!=0 group by assetHold1.finprodMarketId,assetHold1.finprodAbbr,assetHold1.ptlIssueType,assetHold1.assetRatioTemp
